pub fn gzip_file_roundtrip(data: &[u8], iters: u64) -> String {
    let input_crc = unsafe { crc32(0, data.as_ptr(), data.len() as c_uint) as u64 };
    let mut digest = fold(0, data.len() as u64);

    let mut last_w = 0i32;
    let mut last_flush = 0i32;
    let mut last_close_w = 0i32;
    let mut last_r = 0i32;
    let mut last_eof = 0i32;
    let mut last_errnum = 0i32;
    let mut last_close_r = 0i32;
    let mut last_total_read = 0u64;
    let mut last_out_crc = 0u64;
    let mut last_eq = 0u64;
    let mut last_err_strlen = 0u64;

    for iter in 0..iters {
        let path = format!(
            "{}/optipng_raw_harness_{}_{}_{}.gz",
            std::env::temp_dir().display(),
            std::process::id(),
            data.len(),
            iter
        );
        let c_path = cstring_lossy_no_nul(&path);
        let mode_w = CString::new("wb").unwrap();
        let mode_r = CString::new("rb").unwrap();

        unsafe {
            let wf = gzopen(c_path.as_ptr(), mode_w.as_ptr());
            if wf.is_null() {
                last_w = -1;
                last_flush = -1;
                last_close_w = -1;
                last_r = -1;
                last_eof = -1;
                last_errnum = -1;
                last_close_r = -1;
                last_total_read = 0;
                last_out_crc = 0;
                last_eq = 0;
                last_err_strlen = 0;
                digest = fold(digest, 0xdead);
                let _ = fs::remove_file(&path);
                continue;
            }

            last_w = gzwrite(wf, data.as_ptr() as *const c_void, data.len() as c_uint);
            last_flush = gzflush(wf, 4);
            last_close_w = gzclose_w(wf);

            let rf = gzopen(c_path.as_ptr(), mode_r.as_ptr());
            if rf.is_null() {
                last_r = -1;
                last_eof = -1;
                last_errnum = -1;
                last_close_r = -1;
                last_total_read = 0;
                last_out_crc = 0;
                last_eq = 0;
                last_err_strlen = 0;
                digest = fold(digest, 0xbeef);
                let _ = fs::remove_file(&path);
                continue;
            }

            let mut out = Vec::with_capacity(data.len().max(1));
            let mut buf = vec![0u8; 8192];
            loop {
                let n = gzread(rf, buf.as_mut_ptr() as *mut c_void, buf.len() as c_uint);
                last_r = n;
                if n > 0 {
                    out.extend_from_slice(&buf[..n as usize]);
                } else {
                    break;
                }
            }

            last_eof = gzeof(rf);
            let mut errnum = 0i32;
            let errp = gzerror(rf, &mut errnum);
            last_errnum = errnum;
            last_err_strlen = if errp.is_null() {
                0
            } else {
                let mut n = 0usize;
                while *errp.add(n) != 0 {
                    n += 1;
                }
                n as u64
            };
            gzclearerr(rf);
            last_close_r = gzclose_r(rf);

            last_total_read = out.len() as u64;
            last_out_crc = crc32(0, out.as_ptr(), out.len() as c_uint) as u64;
            last_eq = (out == data) as u64;

            let mut d = 0u64;
            d = fold(d, input_crc);
            d = fold(d, last_w as u32 as u64);
            d = fold(d, last_flush as u32 as u64);
            d = fold(d, last_close_w as u32 as u64);
            d = fold(d, last_r as u32 as u64);
            d = fold(d, last_eof as u32 as u64);
            d = fold(d, last_errnum as u32 as u64);
            d = fold(d, last_close_r as u32 as u64);
            d = fold(d, last_total_read);
            d = fold(d, last_out_crc);
            d = fold(d, last_eq);
            d = fold(d, last_err_strlen);
            digest = fold(digest, d);
        }

        let _ = fs::remove_file(&path);
    }

    format!(
        "op=gzip_file_roundtrip in_len={} in_crc={:08x} w={} flush={} close_w={} r={} eof={} errnum={} close_r={} total_read={} out_crc={:08x} eq={} digest={:016x}",
        data.len(),
        input_crc,
        last_w,
        last_flush,
        last_close_w,
        last_r,
        last_eof,
        last_errnum,
        last_close_r,
        last_total_read,
        last_out_crc,
        last_eq,
        digest
