    format!(
        "op=zlib_deflate_inflate_stream in_len={} in_crc={:08x} dinit={} def={} dreset={} dend={} iinit={} inf={} ireset={} iend={} comp={} decomp={} out_crc={:08x} eq={} digest={:016x}",
        data.len(),
        input_crc,
        last_init_d,
        last_def,
        last_reset_d,
        last_end_d,
        last_init_i,
        last_inf,
        last_reset_i,
        last_end_i,
        last_comp_size,
        last_decomp_size,
        last_out_crc,
        last_eq,
        digest
