pub fn png_write_read_roundtrip(data: &[u8], iters: u64) -> String {
    let width = 32u32;
    let height = ((data.len() as u32).saturating_add(width - 1) / width).max(1);
    let rowbytes = width as usize;
    let total = rowbytes * height as usize;

    let mut pixels = vec![0u8; total];
    let copy_len = data.len().min(total);
    pixels[..copy_len].copy_from_slice(&data[..copy_len]);

    let mut row_ptrs: Vec<*mut c_uchar> = Vec::with_capacity(height as usize);
    for y in 0..height as usize {
        row_ptrs.push(pixels[y * rowbytes..].as_mut_ptr());
    }

    let input_fold = fold_bytes(0, &pixels);
    let version_num = unsafe { png_access_version_number() as u64 };

    let mut digest = fold(0, data.len() as u64);
    let mut last_sig_cmp = -1i32;
    let mut last_png_size = 0u64;
    let mut last_w = 0u64;
    let mut last_h = 0u64;
    let mut last_rb = 0u64;
    let mut last_rows_null = 1u64;
    let mut last_dec_crc = 0u64;
    let mut last_eq = 0u64;
    let mut last_write_ok = 0u64;
    let mut last_read_ok = 0u64;

    for _ in 0..iters {
        unsafe {
            let ver = png_get_libpng_ver(ptr::null());
            let mut writer = MemWriter {
                buf: Vec::new(),
                failed: 0,
            };

            let png_w = png_create_write_struct(ver, ptr::null_mut(), None, None);
            if png_w.is_null() {
                digest = fold(digest, 1);
                continue;
            }
            let info_w = png_create_info_struct_core(png_w as *const _);
            if info_w.is_null() {
                let mut pw = png_w;
                png_destroy_write_struct(&mut pw, ptr::null_mut());
                digest = fold(digest, 2);
                continue;
            }

            png_set_error_fn(
                png_w as *mut _,
                ptr::null_mut(),
                Some(png_noop_error),
                Some(png_noop_warn),
            );
            png_set_IHDR(
                png_w as *const _,
                info_w as *mut _,
                width,
                height,
                8,
                0,
                0,
                0,
                0,
            );
            png_set_rows(png_w as *const _, info_w as *mut _, row_ptrs.as_mut_ptr() as *mut _);
            png_set_write_fn(
                png_w as *mut _,
                &mut writer as *mut _ as *mut c_void,
                Some(png_write_cb),
                Some(png_flush_cb),
            );
            png_write_png(png_w as *mut _, info_w as *mut _, 0, ptr::null_mut());
            last_write_ok = (writer.failed == 0) as u64;
            last_png_size = writer.buf.len() as u64;

            let mut pw = png_w;
            let mut iw = info_w;
            png_destroy_write_struct(&mut pw, &mut iw as *mut _ as *mut _);

            last_sig_cmp = if writer.buf.len() >= 8 {
                png_sig_cmp(writer.buf.as_ptr(), 0, 8)
            } else {
                -1
            };

            let mut reader = MemReader {
                data: writer.buf,
                pos: 0,
                failed: 0,
            };

            let png_r = png_create_read_struct(ver, ptr::null_mut(), None, None);
            if png_r.is_null() {
                digest = fold(digest, 3);
                continue;
            }
            let info_r = png_create_info_struct_core(png_r as *const _);
            if info_r.is_null() {
                let mut pr = png_r;
                png_destroy_read_struct(&mut pr, ptr::null_mut(), ptr::null_mut());
                digest = fold(digest, 4);
                continue;
            }

            png_set_error_fn(
                png_r as *mut _,
                ptr::null_mut(),
                Some(png_noop_error),
                Some(png_noop_warn),
            );
            png_set_read_fn(
                png_r as *mut _,
                &mut reader as *mut _ as *mut c_void,
                Some(png_read_cb),
            );
            png_read_png(png_r as *mut _, info_r as *mut _, 0, ptr::null_mut());
            last_read_ok = (reader.failed == 0) as u64;

            last_w = png_get_image_width(png_r as *const _, info_r as *const _) as u64;
            last_h = png_get_image_height(png_r as *const _, info_r as *const _) as u64;
            last_rb = png_get_rowbytes(png_r as *const _, info_r as *const _) as u64;
            let rows = png_get_rows(png_r as *const _, info_r as *const _);
            last_rows_null = rows.is_null() as u64;

            let mut dec = Vec::new();
            if !rows.is_null() && last_h > 0 && last_rb > 0 {
                let h = last_h as usize;
                let rb = last_rb as usize;
                dec.reserve(h.saturating_mul(rb));
                for y in 0..h {
                    let rp = *rows.add(y);
                    if rp.is_null() {
                        break;
                    }
                    let slice = std::slice::from_raw_parts(rp as *const u8, rb);
                    dec.extend_from_slice(slice);
                }
            }

            last_dec_crc = crc32(0, dec.as_ptr(), dec.len() as c_uint) as u64;
            last_eq = (dec == pixels) as u64;

            let mut pr = png_r;
            let mut ir = info_r;
            png_destroy_read_struct(&mut pr, &mut ir as *mut _ as *mut _, ptr::null_mut());

            let mut d = 0u64;
            d = fold(d, input_fold);
            d = fold(d, version_num);
            d = fold(d, last_sig_cmp as u32 as u64);
            d = fold(d, last_png_size);
            d = fold(d, last_w);
            d = fold(d, last_h);
            d = fold(d, last_rb);
            d = fold(d, last_rows_null);
            d = fold(d, last_dec_crc);
            d = fold(d, last_eq);
            d = fold(d, last_write_ok);
            d = fold(d, last_read_ok);
            digest = fold(digest, d);
        }
    }

    format!(
        "op=png_write_read_roundtrip in_len={} sig_cmp={} png_size={} width={} height={} rowbytes={} rows_null={} dec_crc={:08x} eq={} w_ok={} r_ok={} digest={:016x}",
        data.len(),
        last_sig_cmp,
        last_png_size,
        last_w,
        last_h,
        last_rb,
        last_rows_null,
        last_dec_crc,
        last_eq,
        last_write_ok,
        last_read_ok,
        digest
    )
}

