            let _ = opng_path_replace_dir(p2.as_mut_ptr(), p2.len(), c_src.as_ptr(), ndir.as_ptr());
            let _ = opng_path_make_backup(p3.as_mut_ptr(), p3.len(), c_src.as_ptr());
