            rf = fold(rf, r4 as u32 as u64);
            for b in [&buf1, &buf2, &buf3, &buf4] {
                for &ch in b.iter() {
                    rf = fold(rf, ch as u8 as u64);
                }
            }
            last_ratio_fold = rf;

            let mut d = 0u64;
            d = fold(d, input_fold);
            d = fold(d, last_parse as u32 as u64);
            d = fold(d, last_count);
            d = fold(d, last_first);
            d = fold(d, last_next);
            d = fold(d, last_last);
            d = fold(d, last_prev);
            d = fold(d, last_ratio_fold);
            digest = fold(digest, d);
