fn fold_bytes(mut acc: u64, bytes: &[u8]) -> u64 {
    for &b in bytes {
        acc = fold(acc, b as u64);
    }
    acc
}

fn cstring_lossy_no_nul(s: &str) -> CString {
    let mut v = s.as_bytes().to_vec();
    for b in &mut v {
        if *b == 0 {
            *b = b'_';
        }
    }
    match CString::new(v) {
        Ok(c) => c,
        Err(_) => CString::new("x").unwrap_or_else(|_| unsafe { CString::from_vec_unchecked(vec![b'x']) }),
    }
}

