pub fn png_write_read_roundtrip(data: &[u8], iters: u64) -> String {
    let width = 32u32;
    let height = ((data.len() as u32).saturating_add(width - 1) / width).max(1);
    let rowbytes = width as usize;
    let total = rowbytes * height as usize;

    let mut pixels = vec![0u8; total];
