                png_w as *const _,
                info_w as *mut _,
                width,
                height,
                8,
                3,
                1,
                0,
                0,
            );

            let mut palette = [
                png_color {
                    red: 0,
                    green: 0,
                    blue: 0,
                },
                png_color {
                    red: 255,
                    green: 0,
                    blue: 0,
                },
                png_color {
                    red: 0,
                    green: 255,
                    blue: 0,
                },
                png_color {
                    red: 255,
                    green: 255,
                    blue: 255,
