            trans_color.index = 3;
            let trans: [u8; 4] = [255, 128, 255, 0];
            png_set_tRNS(
                png_w as *mut _,
                info_w as *mut _,
                trans.as_ptr(),
                4,
                &trans_color as *const _,
            );

            let mut bkgd = MaybeUninit::<png_color_16>::zeroed().assume_init();
            bkgd.index = 1;
            png_set_bKGD(png_w as *const _, info_w as *mut _, &bkgd as *const _);

