        "op=pnm_roundtrip in_len={} in_crc={:08x} hdr={} valid={} sample_size={} mem_size={} get_bytes={} get_values={} put_hdr={} put_bytes={} put_values={} out_size={} digest={:016x}",
        data.len(),
        input_crc,
        last_hdr,
        last_valid,
        last_sample_size,
        last_mem_size,
        last_get_bytes,
        last_get_values,
        last_put_hdr,
        last_put_bytes,
        last_put_values,
        last_out_size,
        digest
    )
}

