pub fn gzip_fd_printf(data: &[u8], iters: u64) -> String {
    let input_crc = unsafe { crc32(0, data.as_ptr(), data.len() as c_uint) as u64 };
    let msg = cstring_lossy_no_nul("fmt");
    let mode_w = cstring_lossy_no_nul("wb");
    let mode_r = cstring_lossy_no_nul("rb");
    let fmt = cstring_lossy_no_nul("%s:%d:%u\n");
    let mut digest = fold(0, data.len() as u64);
    let mut last_open = 0u64;
    let mut last_printf = 0i32;
    let mut last_write = 0i32;
    let mut last_close = 0i32;
    let mut last_read = 0u64;
    let mut last_crc = 0u64;
    let mut last_eq = 0u64;

    for iter in 0..iters {
        let path = format!(
            "{}/optipng_raw_harness_gzdopen_{}_{}.gz",
            std::env::temp_dir().display(),
            data.len(),
            iter
        );

        let file_res = std::fs::OpenOptions::new()
            .create(true)
            .write(true)
            .truncate(true)
            .open(&path);
        let fd = match file_res {
            Ok(f) => f.into_raw_fd(),
            Err(_) => {
                digest = fold(digest, 0x9898);
                continue;
            }
        };

        unsafe {
            let gf = gzdopen(fd, mode_w.as_ptr());
            last_open = (!((gf as *mut c_void).is_null())) as u64;
            if (gf as *mut c_void).is_null() {
                let _ = fs::remove_file(&path);
                digest = fold(digest, 0x9899);
                continue;
            }
            let _ = gzbuffer(gf as *mut _, 8192);
            last_printf = gzprintf(gf as *mut _, fmt.as_ptr(), msg.as_ptr(), data.len() as c_int, (input_crc & 0xffff_ffff) as c_uint);
            last_write = gzwrite(gf as *mut _, data.as_ptr() as *const c_void, data.len() as c_uint);
            last_close = gzclose(gf as *mut _);

            let rf = gzopen(cstring_lossy_no_nul(&path).as_ptr(), mode_r.as_ptr());
            if (rf as *mut c_void).is_null() {
                digest = fold(digest, 0x989a);
                let _ = fs::remove_file(&path);
                continue;
            }
            let mut out = Vec::new();
            let mut buf = vec![0u8; 4096];
            loop {
                let n = gzread(rf as *mut _, buf.as_mut_ptr() as *mut c_void, buf.len() as c_uint);
                if n <= 0 {
                    break;
                }
                out.extend_from_slice(&buf[..n as usize]);
            }
            let _ = gzclose(rf as *mut _);
            last_read = out.len() as u64;
            last_crc = crc32(0, out.as_ptr(), out.len() as c_uint) as u64;
            last_eq = out.windows(data.len()).any(|w| w == data) as u64;
        }

        let mut d = 0u64;
        d = fold(d, input_crc);
        d = fold(d, last_open);
        d = fold(d, last_printf as u32 as u64);
        d = fold(d, last_write as u32 as u64);
        d = fold(d, last_close as u32 as u64);
        d = fold(d, last_read);
        d = fold(d, last_crc);
        d = fold(d, last_eq);
        digest = fold(digest, d);
        let _ = fs::remove_file(&path);
    }

    format!(
        "op=gzip_fd_printf in_len={} in_crc={:08x} open={} printf={} write={} close={} read={} out_crc={:08x} eq={} digest={:016x}",
        data.len(),
        input_crc,
        last_open,
        last_printf,
        last_write,
        last_close,
        last_read,
        last_crc,
        last_eq,
        digest
    )
}

#[repr(C)]
struct InflateBackIn {
    data: Vec<u8>,
    pos: usize,
    scratch: Vec<u8>,
}

#[repr(C)]
struct InflateBackOut {
    out: Vec<u8>,
}

unsafe extern "C" fn infback_in(desc: *mut c_void, buf: *mut *mut c_uchar) -> c_uint {
    if desc.is_null() || buf.is_null() {
        return 0;
    }
    let st = &mut *(desc as *mut InflateBackIn);
    if st.pos >= st.data.len() {
        *buf = ptr::null_mut();
        return 0;
    }
    let take = (st.data.len() - st.pos).min(4096);
    st.scratch.clear();
    st.scratch
        .extend_from_slice(&st.data[st.pos..st.pos + take]);
    st.pos += take;
    *buf = st.scratch.as_mut_ptr();
    take as c_uint
}

unsafe extern "C" fn infback_out(desc: *mut c_void, buf: *mut c_uchar, len: c_uint) -> c_int {
    if desc.is_null() || (buf.is_null() && len != 0) {
        return 1;
    }
    let st = &mut *(desc as *mut InflateBackOut);
    let slice = std::slice::from_raw_parts(buf as *const u8, len as usize);
    st.out.extend_from_slice(slice);
    0
}

pub fn zlib_inflate_back(data: &[u8], iters: u64) -> String {
