            png_set_filter(png_w as *mut _, 0, 0x08);
            png_set_IHDR(
                png_w as *const _,
                info_w as *mut _,
                width,
                height,
                8,
                3,
                1,
                0,
                0,
            );

            let mut palette = [
                png_color {
                    red: 0,
                    green: 0,
                    blue: 0,
                },
                png_color {
                    red: 255,
                    green: 0,
                    blue: 0,
                },
                png_color {
                    red: 0,
                    green: 255,
                    blue: 0,
                },
                png_color {
                    red: 255,
                    green: 255,
                    blue: 255,
                },
            ];
            png_set_PLTE(png_w as *mut _, info_w as *mut _, palette.as_ptr(), 4);

            let hist: [u16; 4] = [10, 20, 30, 40];
            png_set_hIST(png_w as *const _, info_w as *mut _, hist.as_ptr());

