            let trans: [u8; 4] = [255, 128, 255, 0];
            png_set_tRNS(
                png_w as *mut _,
                info_w as *mut _,
                trans.as_ptr(),
                4,
                &trans_color as *const _,
            );

            let mut bkgd = MaybeUninit::<png_color_16>::zeroed().assume_init();
            bkgd.index = 1;
            png_set_bKGD(png_w as *const _, info_w as *mut _, &bkgd as *const _);

            png_set_rows(png_w as *const _, info_w as *mut _, row_ptrs.as_mut_ptr() as *mut _);
            png_set_write_fn(
                png_w as *mut _,
                &mut writer as *mut _ as *mut c_void,
                Some(png_write_cb),
                Some(png_flush_cb),
